141	    private static Optional<String> toMBeanName(Map<String, String> tags) {
142	        List<Map.Entry<String, String>> filteredTags = tags.entrySet().stream()
143	                .filter(entry -> !entry.getValue().isEmpty())
144	                .toList();
145	        if (!filteredTags.isEmpty()) {
146	            String tagsString = filteredTags.stream()
147	                    .map(entry -> entry.getKey() + "=" + Sanitizer.jmxSanitize(entry.getValue()))
148	                    .collect(Collectors.joining(","));
149	            return Optional.of(tagsString);
150	        } else {
151	            return Optional.empty();
152	        }
153	    }
154	
155	    private static Optional<String> toScope(Map<String, String> tags) {
156	        List<Map.Entry<String, String>> filteredTags = tags.entrySet().stream()
157	                .filter(entry -> !entry.getValue().isEmpty())
158	                .toList();
159	        if (!filteredTags.isEmpty()) {
160	            // convert dot to _ since reporters like Graphite typically use dot to represent hierarchy
161	            String tagsString = filteredTags.stream()
162	                    .sorted(Map.Entry.comparingByKey())
163	                    .map(entry -> entry.getKey() + "." + entry.getValue().replaceAll("\\.", "_"))
164	                    .collect(Collectors.joining("."));
165	            return Optional.of(tagsString);
166	        } else {
167	            return Optional.empty();
168	        }
169	    }
170	}
